INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-ariana-2026-editorial-v2-ht', 'article', id, updated_at, 'ht', '{"title":"Ariana Lafond : soti nan TikTok pou rive sou sèn entènasyonal","subtitle":"Soti Togo rive Larisi, avèk yon remiz machin anonse nan Lachin, kreyatris ayisyèn nan elaji pakou li an 2026.","body":"Ariana Milagro Lafond ap bati yon prezans ki depase rezo sosyal yo. Viktwa li nan House of Challenge nan Togo ak patisipasyon li nan yon festival entènasyonal nan Larisi make ane 2026 li. Yon piblikasyon sou kont LinkedIn Bovann K. anonse tou yon remiz machin nan Lachin, ki lye ak pri li nan konpetisyon an.\n\n## Yon odyans plizyè milyon moun\n\nYon kaptire pwofil TikTok @_ariouuu, transmèt bay Geovyora 3 oktòb 2026, montre 18,4 milyon abòne, 332,5 milyon total renmen ak yon badj verifikasyon. Chif sa yo soti nan kaptire a epi yo kapab evolye. Selon Le Nouvelliste, Ticket Magazine te chwazi li kòm enfliyansez ane 2025.\n\n## Yon viktwa nan Togo\n\nNan dat 11 avril 2026, Ariana genyen wityèm edisyon House of Challenge nan Lomé. Le Nouvelliste souliye mobilizasyon sou entènèt pou li. Juno7 rapòte sipò piblik ayisyen an ak dyaspora a, ansanm ak prezans sè jimo li, Djephkina Lafond. Rekonpans yo anonse yo gen ladan yon machin, yon vwayaj Lachin ak finansman antreprenarya. Li resevwa tou tit anbasadris pwogram nan.\n\n## Avèk Djephkina nan Larisi\n\nNan mwa septanm, de sè yo patisipe nan Festival entènasyonal jèn yo nan Ekaterinbourg. Sit ofisyèl la bay dat 11 rive 17 septanm 2026 epi li anonse 10 000 patisipan ak 191 peyi reprezante.\n\nNan atik 14 septanm li a, Bèlide Magazine rapòte Ariana pran lapawòl pandan yon konferans anime pa Dmitry Chernyshenko, vis premye minis Larisi. Selon magazin nan, li deklare li abòne ak kont Ariana.\n\n## Yon remiz machin anonse nan Lachin\n\nKont Bovann K. fè konnen sou LinkedIn li nan Lachin pou remiz machin Ariana a. Togo Today te deja rapòte an avril pri a gen ladan yon machin pou chwazi nan Lachin ak yon vwayaj ki finanse. Anons sa a pa presize dat machin nan ap livre ann Ayiti.\n\nEtap sa yo konekte vizibilite dijital Ariana ak rankont entènasyonal. Pakou li montre plas kreyatè ayisyen yo kapab pran nan espas kiltirèl ak medya pi lwen pase peyi yo."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-ariana-2026-editorial' AND slug='ariana-lafond-tiktok-scene-internationale' AND locale='fr' AND updated_at='2026-10-04T02:20:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-ariana-2026-editorial-v2-en', 'article', id, updated_at, 'en', '{"title":"Ariana Lafond: from TikTok to the international stage","subtitle":"From Togo to Russia, with a car handover announced in China, the Haitian creator expands her international journey in 2026.","body":"Ariana Milagro Lafond is building a presence beyond social media. Her House of Challenge victory in Togo and participation in an international festival in Russia mark her 2026 journey. A post on the Bovann K. LinkedIn account also announces a car handover in China connected to her competition prize.\n\n## An audience of millions\n\nA screenshot of her TikTok profile @_ariouuu, provided to Geovyora on October 3, 2026, shows 18.4 million followers, 332.5 million total likes and a verification badge. These figures reflect that screenshot and may change. According to Le Nouvelliste, Ticket Magazine named her its influencer of the year for 2025.\n\n## A victory in Togo\n\nOn April 11, 2026, Ariana wins the eighth edition of House of Challenge in Lomé. Le Nouvelliste highlights the online support behind her participation. Juno7 reports support from Haiti and its diaspora, alongside the presence of her twin sister, Djephkina Lafond. The announced prizes include a vehicle, a trip to China and entrepreneurial funding. She is also named an ambassador for the program.\n\n## With Djephkina in Russia\n\nIn September, the sisters attend the International Festival of Youth in Ekaterinburg. The official website lists September 11–17, 2026, and announces 10,000 participants and 191 countries represented.\n\nIn its September 14 report, Bèlide Magazine says Ariana speaks during a conference led by Russian Deputy Prime Minister Dmitry Chernyshenko. According to the magazine, he says he follows her account.\n\n## A car handover announced in China\n\nThe Bovann K. account states on LinkedIn that he is in China for Ariana’s car handover. Togo Today had reported in April that the prize included a car to be selected in China and a funded trip. The announcement does not specify when the vehicle will be delivered to Haiti.\n\nThese milestones connect Ariana’s digital visibility with international encounters. Her journey illustrates the space Haitian creators can occupy in cultural and media settings beyond their country."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-ariana-2026-editorial' AND slug='ariana-lafond-tiktok-scene-internationale' AND locale='fr' AND updated_at='2026-10-04T02:20:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-ariana-2026-editorial-v2-pt-BR', 'article', id, updated_at, 'pt-BR', '{"title":"Ariana Lafond: do TikTok ao cenário internacional","subtitle":"Do Togo à Rússia, com a entrega de um carro anunciada na China, a criadora haitiana amplia sua trajetória em 2026.","body":"Ariana Milagro Lafond constrói uma presença que vai além das redes sociais. Sua vitória no House of Challenge, no Togo, e sua participação em um festival internacional na Rússia marcam sua trajetória em 2026. Uma publicação na conta Bovann K. no LinkedIn também anuncia a entrega de um carro na China, ligada ao prêmio da competição.\n\n## Uma audiência de milhões\n\nUma captura do perfil TikTok @_ariouuu, enviada à Geovyora em 3 de outubro de 2026, mostra 18,4 milhões de seguidores, 332,5 milhões de curtidas totais e um selo de verificação. Os números correspondem à captura e podem mudar. Segundo Le Nouvelliste, a Ticket Magazine a escolheu como influenciadora do ano de 2025.\n\n## Uma vitória no Togo\n\nEm 11 de abril de 2026, Ariana vence a oitava edição do House of Challenge em Lomé. Le Nouvelliste destaca a mobilização online em seu apoio. A Juno7 relata o apoio do público haitiano e da diáspora, além da presença de sua irmã gêmea, Djephkina Lafond. Os prêmios anunciados incluem um veículo, uma viagem à China e financiamento para empreendedorismo. Ela também é nomeada embaixadora do programa.\n\n## Com Djephkina na Rússia\n\nEm setembro, as irmãs participam do Festival Internacional da Juventude em Ekaterinburg. O site oficial informa as datas de 11 a 17 de setembro de 2026 e anuncia 10 mil participantes e 191 países representados.\n\nEm sua reportagem de 14 de setembro, a Bèlide Magazine relata que Ariana fala durante uma conferência conduzida pelo vice-primeiro-ministro russo Dmitry Chernyshenko. Segundo a revista, ele declara seguir a conta dela.\n\n## Uma entrega de carro anunciada na China\n\nA conta Bovann K. informa no LinkedIn que ele está na China para a entrega do carro de Ariana. Em abril, o Togo Today já havia informado que o prêmio incluía um carro a ser escolhido na China e uma viagem financiada. O anúncio não especifica a data de entrega do veículo no Haiti.\n\nEssas etapas conectam a visibilidade digital de Ariana a encontros internacionais. Sua trajetória ilustra o espaço que criadores haitianos podem ocupar em ambientes culturais e midiáticos além de seu país."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-ariana-2026-editorial' AND slug='ariana-lafond-tiktok-scene-internationale' AND locale='fr' AND updated_at='2026-10-04T02:20:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-ariana-2026-editorial-v2-es', 'article', id, updated_at, 'es', '{"title":"Ariana Lafond: de TikTok al escenario internacional","subtitle":"Del Togo a Rusia, con una entrega de automóvil anunciada en China, la creadora haitiana amplía su trayectoria en 2026.","body":"Ariana Milagro Lafond construye una presencia que va más allá de las redes sociales. Su victoria en House of Challenge, en Togo, y su participación en un festival internacional en Rusia marcan su trayectoria en 2026. Una publicación en la cuenta Bovann K. de LinkedIn anuncia también una entrega de automóvil en China vinculada a su premio en la competición.\n\n## Una audiencia de millones\n\nUna captura del perfil de TikTok @_ariouuu, enviada a Geovyora el 3 de octubre de 2026, muestra 18,4 millones de seguidores, 332,5 millones de Me gusta totales y una insignia de verificación. Estas cifras corresponden a la captura y pueden cambiar. Según Le Nouvelliste, Ticket Magazine la eligió como influenciadora del año 2025.\n\n## Una victoria en Togo\n\nEl 11 de abril de 2026, Ariana gana la octava edición de House of Challenge en Lomé. Le Nouvelliste destaca la movilización en línea que la apoyó. Juno7 informa del apoyo del público haitiano y de la diáspora, además de la presencia de su hermana gemela, Djephkina Lafond. Los premios anunciados incluyen un vehículo, un viaje a China y financiación para emprendimiento. También es nombrada embajadora del programa.\n\n## Con Djephkina en Rusia\n\nEn septiembre, las hermanas participan en el Festival Internacional de la Juventud en Ekaterimburgo. El sitio oficial indica las fechas del 11 al 17 de septiembre de 2026 y anuncia 10 000 participantes y 191 países representados.\n\nEn su artículo del 14 de septiembre, Bèlide Magazine informa de que Ariana interviene en una conferencia dirigida por el viceprimer ministro ruso Dmitry Chernyshenko. Según la revista, él declara seguir su cuenta.\n\n## Una entrega de automóvil anunciada en China\n\nLa cuenta Bovann K. afirma en LinkedIn que está en China para la entrega del automóvil de Ariana. Togo Today ya había informado en abril de que el premio incluía un vehículo para elegir en China y un viaje financiado. El anuncio no especifica cuándo se entregará el vehículo en Haití.\n\nEstas etapas conectan la visibilidad digital de Ariana con encuentros internacionales. Su trayectoria ilustra el espacio que los creadores haitianos pueden ocupar en ámbitos culturales y mediáticos más allá de su país."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-ariana-2026-editorial' AND slug='ariana-lafond-tiktok-scene-internationale' AND locale='fr' AND updated_at='2026-10-04T02:20:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-mrbeast-2026-ht', 'article', id, updated_at, 'ht', '{"title":"MrBeast, soti YouTube rive Beast Land: lè videyo tounen eksperyans reyèl","subtitle":"Jimmy Donaldson bati yon linivè ki depase videyo yo. Pak, pwodwi ak pwojè filantwopik montre kijan odyans yon kreyatè ka tounen yon biznis, ak nouvo responsablite.","image_credit":"Foto Tyren Redd, sous David Soled, rekadraj Edward of York, ti imaj la redimansyone pa Wikimedia Commons — CC BY 4.0. Foto a te rekadre epi ti imaj la te redimansyone.","body":"Yon defi ki fasil pou konprann, yon rekonpans enpresyonan ak yon montaj ki pa kite anpil poz: Jimmy Donaldson, moun plis konnen sou non MrBeast, fè fòmil sa a tounen youn nan fòma YouTube ki pi fasil pou rekonèt. Kounye a, linivè li a pa rete nan videyo sèlman. Li pwolonje nan espas amizman, pwodwi ak aktivite filantwopik. Kesyon an pa sèlman konbyen moun k ap gade, men tou ki sa yon odyans konsa ka ede konstwi, ak ki responsablite sa pote.\n\nNan novanm 2025, Reuters te rapòte videyo MrBeast yo te depase 100 milya vizyalizasyon sou YouTube. Nan menm peryòd la, Beast Land te louvri nan Riyad. Pak sa a transfòme defi videyo yo an atraksyon ak eprèv fizik. Pasaj soti sou ekran pou rive nan yon espas reyèl montre kijan yon fòma dijital ka tounen eksperyans fanatik yo achte epi viv. [Reuters](https://www.reuters.com/business/media-telecom/worlds-top-youtuber-mrbeast-launches-saudi-theme-park-2025-11-13/)\n\n## Yon fòma ki tounen mak\n\nRèg videyo yo fasil pou konprann: piblik la wè sa patisipan yo riske, sa yo dwe fè ak sa yo ka genyen. Klète sa a pèmèt yon moun antre nan yon videyo menm si li pa konnen chanèl la. Beast Land reprann menm mekanis la, men vizitè a pa rete devan ekran ankò: li vin patisipan.\n\nPou kreyatè yo, elajisman sa a ouvri plizyè posiblite. Menm kominote a ka suiv chanèl la, eseye yon pwodwi oswa achte yon eksperyans. Men repitasyon kreyatè a mache avèk chak nouvo aktivite. Konfyans videyo yo bati a ka soutni biznis la, men li ka febli tou si pwomès, règ oswa piblisite yo pa klè.\n\n## Filantwopi dwe depase anons\n\nFilantwopi fè pati imaj piblik MrBeast. An 2025, Beast Philanthropy ak Rockefeller Foundation te anonse yon patenarya pou mete odyans Donaldson an ansanm ak eksperyans fondasyon an. Lè yo te fè anons lan, patnè yo poko te fikse tout domèn yo t ap travay sou yo ni bay detay sou pwojè ansanm yo. Se te yon angajman pou devlope, se pa yon rapò ki montre rezilta yo te deja reyalize. [Associated Press](https://apnews.com/article/mrbeast-jimmy-donaldson-rockefeller-foundation-18f75839ecf7276a14bfcaf7caba07ba)\n\nDistenksyon sa a enpòtan. Yon anons ka atire atansyon sou yon pwoblèm, men enpak la mezire sou tan: kiyès ki fikse priyorite yo, ki kote lajan an ale, epi kijan moun ki konsène yo patisipe nan desizyon yo? Yon gwo odyans ka akselere yon ranmasaj lajan oswa fè yon pwojè vin pi vizib. Li pa ranplase transparans sou fason pwojè a mache.\n\n## Lè biznis la vin gwo, detay yo konte\n\nMak la grandi, epi kèk nan pratik li yo vin anba egzamen. An septanm 2025, Reuters te rapòte CARU, yon òganizasyon ameriken k ap egzamine piblisite ki vize timoun, te rekòmande chanjman sou fason yo make piblisite, kèk mesaj sou Feastables, konkou ak koleksyon done sou timoun. Ekip MrBeast la te reponn yo te chanje oswa sispann pratik ki konsène yo, epi li te konteste kèk nan konklizyon yo. [Reuters](https://www.reuters.com/business/media-telecom/mrbeast-chocolate-ads-were-misleading-us-childrens-watchdog-group-says-2025-09-18/)\n\nAn avril 2026, yon ansyen anplwaye depoze plent kont kèk konpayi ki gen rapò ak Beast Industries. Nan plent lan, li fè akizasyon asèlman ak revokasyon apre li te retounen soti nan konje matènite. Konpayi an rejte akizasyon yo epi li di yo te siprime pòs li nan kad yon reòganizasyon. Yon plent prezante akizasyon, men li pa poukont li yon desizyon tribinal. [Associated Press](https://apnews.com/article/1328b020711e2bef10f0a3f8a1fa1987)\n\n## Enfliyans mezire tou ak konfyans\n\nMrBeast montre kijan yon kreyatè ka transfòme yon langaj entènèt an amizman pou gwo odyans, epi apre sa an mak ak eksperyans fizik. Pwochen defi a mwens espektakilè pou filme: kenbe konfyans piblik la lè biznis la touche timoun, konsomatè, anplwaye ak kominote li vle ede yo tou.\n\nVizyalizasyon yo montre gwosè enfliyans li. Fason li jere responsablite ki mache ak gwosè sa a pral di plis sou kapasite li pou dire."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-mrbeast-2026' AND slug='mrbeast-youtube-beast-land-influence-mondiale' AND locale='fr' AND status='published' AND demo=0 AND updated_at='2026-10-09T00:00:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-mrbeast-2026-en', 'article', id, updated_at, 'en', '{"title":"MrBeast, from YouTube to Beast Land: when videos become real-world experiences","subtitle":"Jimmy Donaldson has built a world beyond videos. Parks, products and philanthropic projects show how a creator’s audience can become a business, with new responsibilities.","image_credit":"Photo by Tyren Redd, source David Soled, crop by Edward of York, thumbnail resized by Wikimedia Commons — CC BY 4.0. Photo cropped and thumbnail resized.","body":"An easy-to-understand challenge, a spectacular prize and editing with little downtime: Jimmy Donaldson, better known as MrBeast, has turned that formula into one of YouTube’s most recognizable formats. His world no longer fits inside a video. It now extends into entertainment venues, products and philanthropic initiatives. The question is not only how many people watch, but what such a large audience can help build and what responsibilities come with it.\n\nIn November 2025, Reuters reported that MrBeast’s videos had passed 100 billion views on YouTube. Around the same time, Beast Land opened in Riyadh. The park turns his challenges into attractions and physical contests. The move from screen to real place shows how a digital format can become an experience fans buy and take part in. [Reuters](https://www.reuters.com/business/media-telecom/worlds-top-youtuber-mrbeast-launches-saudi-theme-park-2025-11-13/)\n\n## A format becomes a brand\n\nThe rules of his videos are quick to grasp: viewers can see what participants risk, what they must do and what they might win. That clarity lets someone join a video even without knowing the channel. Beast Land uses the same mechanics, but visitors are no longer in front of a screen. They become participants themselves.\n\nFor creators, this kind of expansion opens several paths. The same community can follow a channel, try a product or buy an experience. But the creator’s reputation follows every new activity. Trust built through videos can support the business, and it can also weaken if promises, rules or advertising are unclear.\n\n## Philanthropy must go beyond announcements\n\nPhilanthropy is part of MrBeast’s public image. In 2025, Beast Philanthropy and the Rockefeller Foundation announced a partnership intended to combine Donaldson’s reach with the foundation’s experience. At the time of the announcement, the partners had not settled all the focus areas or detailed their joint projects. It was a commitment to develop, not a report of results already achieved. [Associated Press](https://apnews.com/article/mrbeast-jimmy-donaldson-rockefeller-foundation-18f75839ecf7276a14bfcaf7caba07ba)\n\nThat distinction matters. An announcement can draw attention to an issue, but impact is measured over time: who sets priorities, where the money goes and how affected people take part in decisions. A large audience can speed up a fundraiser or make a project visible. It cannot replace transparency about how the project works.\n\n## At scale, details matter\n\nThe brand’s growth has also put some practices under scrutiny. In September 2025, Reuters reported that the US organization CARU had recommended changes involving advertising disclosures, some Feastables messaging, contests and the collection of children’s data. MrBeast’s team responded that the practices in question had been changed or stopped and disputed some of the findings. [Reuters](https://www.reuters.com/business/media-telecom/mrbeast-chocolate-ads-were-misleading-us-childrens-watchdog-group-says-2025-09-18/)\n\nIn April 2026, a former employee filed a complaint against companies connected to Beast Industries. The complaint alleges harassment and termination after she returned from maternity leave. The company rejected the allegations and said her position was eliminated in a reorganization. A complaint sets out allegations. It is not, by itself, a court ruling. [Associated Press](https://apnews.com/article/1328b020711e2bef10f0a3f8a1fa1987)\n\n## Influence is also measured in trust\n\nMrBeast has shown how a creator can turn internet-native language into mass entertainment, then into a brand and a physical experience. His next challenge is less spectacular to film: maintaining public trust as the business also reaches children, consumers, employees and communities it aims to help.\n\nViews explain the scale of his influence. How he responds to the responsibilities that come with that scale will say more about whether it can last."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-mrbeast-2026' AND slug='mrbeast-youtube-beast-land-influence-mondiale' AND locale='fr' AND status='published' AND demo=0 AND updated_at='2026-10-09T00:00:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-mrbeast-2026-pt-BR', 'article', id, updated_at, 'pt-BR', '{"title":"MrBeast, do YouTube ao Beast Land: quando vídeos viram experiências reais","subtitle":"Jimmy Donaldson construiu um universo que vai além dos vídeos. Parques, produtos e projetos filantrópicos mostram como a audiência de um criador pode se transformar em negócio, com novas responsabilidades.","image_credit":"Foto de Tyren Redd, fonte David Soled, recorte de Edward of York, miniatura redimensionada pela Wikimedia Commons — CC BY 4.0. Foto recortada e miniatura redimensionada.","body":"Um desafio fácil de entender, um prêmio impressionante e uma edição sem quase nenhum tempo morto: Jimmy Donaldson, mais conhecido como MrBeast, transformou essa fórmula em um dos formatos mais reconhecíveis do YouTube. Hoje, seu universo não cabe em um vídeo. Ele também está em espaços de entretenimento, produtos e iniciativas filantrópicas. A questão não é apenas quantas pessoas assistem, mas o que uma audiência tão grande permite construir e quais responsabilidades vêm junto.\n\nEm novembro de 2025, a Reuters informou que os vídeos de MrBeast haviam ultrapassado 100 bilhões de visualizações no YouTube. Na mesma época, o Beast Land foi inaugurado em Riade. O parque transforma os desafios dos vídeos em atrações e provas físicas. A passagem da tela para um espaço real mostra como um formato digital pode virar uma experiência que os fãs compram e vivenciam. [Reuters](https://www.reuters.com/business/media-telecom/worlds-top-youtuber-mrbeast-launches-saudi-theme-park-2025-11-13/)\n\n## Um formato que virou marca\n\nAs regras dos vídeos são fáceis de entender: o público vê o que os participantes arriscam, o que precisam fazer e o que podem ganhar. Essa clareza permite que alguém acompanhe um vídeo mesmo sem conhecer o canal. O Beast Land retoma a mesma lógica, mas o visitante deixa de ficar diante da tela e passa a participar.\n\nPara os criadores, essa expansão abre vários caminhos. A mesma comunidade pode acompanhar um canal, experimentar um produto ou comprar uma experiência. Mas a reputação do criador acompanha cada nova atividade. A confiança construída nos vídeos pode fortalecer o negócio e também pode se desgastar se promessas, regras ou publicidade não forem claras.\n\n## Filantropia precisa ir além dos anúncios\n\nA filantropia faz parte da imagem pública de MrBeast. Em 2025, a Beast Philanthropy e a Rockefeller Foundation anunciaram uma parceria para aproximar o alcance de Donaldson da experiência da fundação. Na época do anúncio, os parceiros ainda não haviam definido todas as áreas de atuação nem detalhado os projetos conjuntos. Era um compromisso a desenvolver, não um relatório de resultados já alcançados. [Associated Press](https://apnews.com/article/mrbeast-jimmy-donaldson-rockefeller-foundation-18f75839ecf7276a14bfcaf7caba07ba)\n\nEssa diferença importa. Um anúncio pode chamar atenção para um problema, mas o impacto é medido ao longo do tempo: quem define as prioridades, para onde vai o dinheiro e como as pessoas afetadas participam das decisões? Uma grande audiência pode acelerar uma arrecadação ou dar visibilidade a um projeto. Ela não substitui a transparência sobre como ele funciona.\n\n## Em grande escala, os detalhes importam\n\nO crescimento da marca também colocou algumas práticas sob análise. Em setembro de 2025, a Reuters informou que a organização americana CARU recomendou mudanças relacionadas à identificação de publicidade, a algumas mensagens da Feastables, a concursos e à coleta de dados de crianças. A equipe de MrBeast respondeu que as práticas em questão haviam sido alteradas ou encerradas e contestou algumas conclusões. [Reuters](https://www.reuters.com/business/media-telecom/mrbeast-chocolate-ads-were-misleading-us-childrens-watchdog-group-says-2025-09-18/)\n\nEm abril de 2026, uma ex-funcionária apresentou uma queixa contra empresas ligadas à Beast Industries. Na queixa, ela faz acusações de assédio e demissão após voltar da licença-maternidade. A empresa rejeitou as acusações e afirmou que o cargo foi eliminado em uma reorganização. Uma queixa apresenta alegações. Por si só, não é uma decisão judicial. [Associated Press](https://apnews.com/article/1328b020711e2bef10f0a3f8a1fa1987)\n\n## A influência também se mede pela confiança\n\nMrBeast mostrou como um criador pode transformar a linguagem da internet em entretenimento de massa e, depois, em marca e experiência presencial. Seu próximo desafio é menos espetacular de filmar: manter a confiança do público quando o negócio também alcança crianças, consumidores, funcionários e comunidades que pretende ajudar.\n\nAs visualizações mostram a dimensão de sua influência. A forma como ele responde às responsabilidades que vêm com essa dimensão dirá mais sobre sua capacidade de durar."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-mrbeast-2026' AND slug='mrbeast-youtube-beast-land-influence-mondiale' AND locale='fr' AND status='published' AND demo=0 AND updated_at='2026-10-09T00:00:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-mrbeast-2026-es', 'article', id, updated_at, 'es', '{"title":"MrBeast, de YouTube a Beast Land: cuando los videos se convierten en experiencias reales","subtitle":"Jimmy Donaldson ha creado un universo que va más allá de los videos. Parques, productos y proyectos filantrópicos muestran cómo la audiencia de un creador puede convertirse en un negocio, con nuevas responsabilidades.","image_credit":"Fotografía de Tyren Redd, fuente David Soled, recorte de Edward of York, miniatura redimensionada por Wikimedia Commons — CC BY 4.0. Fotografía recortada y miniatura redimensionada.","body":"Un reto fácil de entender, un premio espectacular y una edición con muy pocas pausas: Jimmy Donaldson, más conocido como MrBeast, convirtió esa fórmula en uno de los formatos más reconocibles de YouTube. Hoy su universo ya no cabe en un video. También se extiende a espacios de entretenimiento, productos e iniciativas filantrópicas. La cuestión no es solo cuántas personas miran, sino qué permite construir una audiencia tan grande y qué responsabilidades trae consigo.\n\nEn noviembre de 2025, Reuters informó que los videos de MrBeast habían superado los 100.000 millones de visualizaciones en YouTube. Por esas mismas fechas abrió Beast Land en Riad, un parque que transforma sus retos en atracciones y pruebas físicas. El paso de la pantalla a un lugar real muestra cómo un formato digital puede convertirse en una experiencia que los fans compran y viven. [Reuters](https://www.reuters.com/business/media-telecom/worlds-top-youtuber-mrbeast-launches-saudi-theme-park-2025-11-13/)\n\n## Un formato convertido en marca\n\nLas reglas de sus videos se entienden rápido: el público ve qué arriesgan los participantes, qué deben hacer y qué pueden ganar. Esa claridad permite que alguien se sume a un video aunque no conozca el canal. Beast Land retoma esa mecánica, pero el visitante deja de estar frente a la pantalla y pasa a participar.\n\nPara los creadores, esta expansión abre varias posibilidades. Una misma comunidad puede seguir un canal, probar un producto o comprar una experiencia. Pero la reputación del creador acompaña cada nueva actividad. La confianza que los videos ayudan a construir puede sostener el negocio y también puede debilitarse si las promesas, las reglas o la publicidad no son claras.\n\n## La filantropía debe ir más allá de los anuncios\n\nLa filantropía forma parte de la imagen pública de MrBeast. En 2025, Beast Philanthropy y la Rockefeller Foundation anunciaron una alianza para combinar el alcance de Donaldson con la experiencia de la fundación. Cuando se hizo el anuncio, los socios todavía no habían definido todos los temas ni detallado los proyectos conjuntos. Era un compromiso por desarrollar, no un balance de resultados ya alcanzados. [Associated Press](https://apnews.com/article/mrbeast-jimmy-donaldson-rockefeller-foundation-18f75839ecf7276a14bfcaf7caba07ba)\n\nLa diferencia importa. Un anuncio puede llamar la atención sobre un problema, pero el impacto se mide con el tiempo: quién fija las prioridades, adónde va el dinero y cómo participan en las decisiones las personas afectadas. Una audiencia grande puede acelerar una recaudación o dar visibilidad a un proyecto. No sustituye la transparencia sobre su funcionamiento.\n\n## A gran escala, los detalles importan\n\nEl crecimiento de la marca también puso algunas prácticas bajo examen. En septiembre de 2025, Reuters informó que la organización estadounidense CARU recomendó cambios relacionados con la identificación de anuncios, algunos mensajes de Feastables, concursos y la recopilación de datos de menores. El equipo de MrBeast respondió que las prácticas señaladas se habían modificado o detenido y cuestionó algunas conclusiones. [Reuters](https://www.reuters.com/business/media-telecom/mrbeast-chocolate-ads-were-misleading-us-childrens-watchdog-group-says-2025-09-18/)\n\nEn abril de 2026, una exempleada presentó una demanda contra empresas relacionadas con Beast Industries. En ella formula acusaciones de acoso y despido después de regresar de su licencia por maternidad. La empresa rechazó las acusaciones y afirmó que el puesto fue eliminado durante una reorganización. Una demanda expone alegaciones. Por sí sola, no constituye una decisión judicial. [Associated Press](https://apnews.com/article/1328b020711e2bef10f0a3f8a1fa1987)\n\n## La influencia también se mide por la confianza\n\nMrBeast ha mostrado cómo un creador puede transformar el lenguaje propio de internet en entretenimiento masivo y luego en una marca y una experiencia física. Su próximo reto es menos espectacular de filmar: conservar la confianza del público cuando el negocio también alcanza a menores, consumidores, empleados y comunidades a las que quiere ayudar.\n\nLas visualizaciones explican el alcance de su influencia. La forma en que responda a las responsabilidades que vienen con ese alcance dirá más sobre su capacidad para perdurar."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-mrbeast-2026' AND slug='mrbeast-youtube-beast-land-influence-mondiale' AND locale='fr' AND status='published' AND demo=0 AND updated_at='2026-10-09T00:00:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-wyclef-jean-2026-ht', 'article', id, updated_at, 'ht', '{"title":"Wyclef Jean: vwa ayisyen ki mennen dyaspora a nan kè mizik popilè","subtitle":"Soti nan Fugees rive nan pwojè ki melanje mizik ak angajman piblik, pakou li montre kijan yon atis ka fè idantite ayisyen tande sou sèn mondyal, epi poukisa vizibilite mande responsabilite tou.","image_credit":"Collision Conf, foto Stephen McCarthy / Sportsfile, Wikimedia Commons — CC BY 2.0. Foto a pa modifye.","body":"Lè Wyclef Jean te monte pou resevwa yon Grammy ak drapo ayisyen an sou zepòl li, li te bay dyaspora a yon imaj ki fasil pou sonje: yon atis ki te grandi Ozetazini san li pa kache kote fanmi li soti. Jès sa a mache ansanm ak yon karyè ki bati sou mizik, men tou sou kapasite pou fè istwa ayisyen an antre nan konvèsasyon ki pi laj pase sèn hip-hop la. [Anbasad Ayiti Ozetazini](https://www.haiti.org/dt_team/wyclef-jean/)\n\n## Soti nan anfans ann Ayiti pou rive nan Fugees\n\nJean te fèt Kwadèboukè, toupre Pòtoprens, epi li te vin jwenn paran li nan Brooklyn lè li te gen nèf an. Apre sa, fanmi an te etabli nan New Jersey. Nan fen ane 1980 yo, li te fòme yon gwoup ak Lauryn Hill ak Pras Michel. Fugees te jwenn siksè entènasyonal ak albòm The Score, ki soti an 1996. Dapre prezantasyon Anbasad Ayiti a, albòm nan te rive nan premye plas klasman Billboard la epi li te genyen de Grammy. [Anbasad Ayiti Ozetazini](https://www.haiti.org/dt_team/wyclef-jean/)\n\nTrant ane apre, albòm nan toujou rasanble piblik. Nan mwa out 2026, Jean ak Hill te entèprete albòm nan antye pou anivèsè li, nan festival Diaspora Calling! nan Wayòm Ini. Chwa mizik yo ak retou duo a fè sonje kèk zèv pa rete sèlman nan klasman: yo tounen yon pwen referans pou plizyè jenerasyon. [Associated Press](https://ny1.com/nyc/all-boroughs/ap-top-news/2026/08/05/qa-ms-lauryn-hill-on-the-diaspora-calling-festival-in-the-uk-the-fugees-legacy-and-dangelo)\n\n## Yon enfliyans ki depase chante yo\n\nYo te sèvi ak renome mizik Jean nan lavi piblik tou. An 2007, prezidan ayisyen René Préval te nonmen li anbasadè itineran, avèk misyon pou fè pwomosyon imaj peyi a aletranje. Wòl ofisyèl sa a te rekonèt enfliyans non li, san sa pa t fè l tounen yon diplomat karyè. [Reuters](https://www.reuters.com/article/lifestyle/rapper-wyclef-jean-to-be-haitis-roving-ambassador-idUSN03411270/)\n\nEnfliyans li parèt pafwa nan fòma moun pa ta atann. An 2024, li te pwodui “Paper Right”, yon mizik li te reyalize ak TIAA ak plizyè lòt atis, sou ekonomi ak transmisyon patrimwàn. Reuters te rapòte lè sa a mizik la te depase 600 000 koute epi li te jenere plis pase 100 000 dola an don pou First Generation Investors, yon òganizasyon ki anseye baz envestisman bay elèv lekòl segondè ki soti nan kominote ki gen mwens resous. Metòd la pale poukont li: sèvi ak yon fòm jèn yo vle koute pou pale de yon sijè yo raman asosye ak mizik. [Reuters](https://www.reuters.com/business/finance/new-money-advice-wyclef-jean-just-dropped-its-rap-2024-02-26/)\n\n## Renome pa ranplase responsabilite\n\nIstwa Yéle Haiti fè sonje angajman piblik dwe mache ak yon jesyon ki klè. Apre tranblemanntè 2010 la, òganizasyon Jean te ko-fonde a te mande don pou Ayiti. Annapre, te gen kesyon sou finans li ak repòtaj sou peman ki te konteste. An 2011, Reuters te site Jean ki te rekonèt òganizasyon an te fè erè, pandan li t ap nye li te sèvi ak lajan Yéle pou enterè pèsonèl li. Asosyasyon an te fèmen an 2012, pandan kesyon sou jesyon li yo te kontinye. [Reuters](https://www.reuters.com/article/lifestyle/wyclef-jean-squandered-haitian-relief-funds-report-idUSTRE7AQ0T2/) · [TheGrio](https://thegrio.com/2012/10/15/wyclef-jeans-charity-yele-haiti-shuts-down-amid-financial-scandal/)\n\nPati sa a pa rezime mizik li, men li fè pati istwa piblik li. Lè yon selebrite mande piblik la sipòte yon kòz, bon entansyon pa sifi: kont yo, rezilta yo ak repons devan kritik yo antre nan konfyans lan tou.\n\nWyclef Jean rete yon figi enfliyans kiltirèl ayisyen paske li te fè yon idantite ak yon dyaspora vin vizib sou sèn entènasyonal, epi li te kontinye chèche nouvo fason pou pale ak piblik la. Pakou li montre fòs enfliyans sa a ak responsabilite ki mache avè l."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-wyclef-jean-2026' AND slug='wyclef-jean-influence-haitienne-diaspora-fugees' AND locale='fr' AND status='published' AND demo=0 AND updated_at='2026-10-09T00:00:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-wyclef-jean-2026-en', 'article', id, updated_at, 'en', '{"title":"Wyclef Jean: the Haitian voice that brought the diaspora into popular music","subtitle":"From the Fugees to projects mixing music with public engagement, his career shows how an artist can bring Haitian identity to global stages and why visibility also carries responsibility.","image_credit":"Collision Conf, photo by Stephen McCarthy / Sportsfile, Wikimedia Commons — CC BY 2.0. Photo unmodified.","body":"When Wyclef Jean went up to accept a Grammy with the Haitian flag over his shoulders, he gave the diaspora an image that was easy to remember: an artist raised in the United States who did not hide where his family came from. That gesture sits alongside a career built on music and on the ability to bring a Haitian story into conversations much wider than hip-hop. [Embassy of Haiti in the United States](https://www.haiti.org/dt_team/wyclef-jean/)\n\n## From a Haitian childhood to the Fugees\n\nBorn in Croix-des-Bouquets, near Port-au-Prince, Jean joined his parents in Brooklyn at age nine. His family later settled in New Jersey. In the late 1980s, he formed a group with Lauryn Hill and Pras Michel. The Fugees found international success with The Score, released in 1996. According to the Embassy of Haiti’s profile, the album reached No. 1 on the Billboard chart and won two Grammy Awards. [Embassy of Haiti in the United States](https://www.haiti.org/dt_team/wyclef-jean/)\n\nThirty years later, the album still brings audiences together. In August 2026, Jean and Hill performed it in full for its anniversary at the Diaspora Calling! festival in the United Kingdom. The set and the duo’s return are reminders that some works do more than stay on charts: they become shared reference points across generations. [Associated Press](https://ny1.com/nyc/all-boroughs/ap-top-news/2026/08/05/qa-ms-lauryn-hill-on-the-diaspora-calling-festival-in-the-uk-the-fugees-legacy-and-dangelo)\n\n## An influence beyond the songs\n\nJean’s musical fame has also been put to use in public life. In 2007, Haitian President René Préval appointed him roving ambassador, with a role promoting the country’s image abroad. The official position recognized the reach of his name without making him a career diplomat. [Reuters](https://www.reuters.com/article/lifestyle/rapper-wyclef-jean-to-be-haitis-roving-ambassador-idUSN03411270/)\n\nHis influence sometimes takes unexpected forms. In 2024, he produced “Paper Right,” a track made with TIAA and several artists about saving and passing on wealth. Reuters reported at the time that the song had passed 600,000 streams and generated more than $100,000 in donations for First Generation Investors, an organization that teaches investing basics to high-school students from underserved communities. The approach is clear: bring a topic rarely associated with music into a form young people want to hear. [Reuters](https://www.reuters.com/business/finance/new-money-advice-wyclef-jean-just-dropped-its-rap-2024-02-26/)\n\n## Fame does not replace accountability\n\nThe story of Yéle Haiti is a reminder that public engagement needs clear management. After the 2010 earthquake, the organization co-founded by Jean solicited donations for Haiti. Its finances later drew questions and reporting about disputed payments. In 2011, Reuters quoted Jean acknowledging that the organization had made mistakes while denying that he had used Yéle funds for personal purposes. The nonprofit closed in 2012, while questions about its management continued. [Reuters](https://www.reuters.com/article/lifestyle/wyclef-jean-squandered-haitian-relief-funds-report-idUSTRE7AQ0T2/) · [TheGrio](https://thegrio.com/2012/10/15/wyclef-jeans-charity-yele-haiti-shuts-down-amid-financial-scandal/)\n\nThis part of his career does not sum up his music, but it belongs to his public history. When a celebrity asks the public to support a cause, good intentions are not enough: accounts, results and responses to criticism also shape trust.\n\nWyclef Jean remains an influential Haitian cultural figure because he made an identity and a diaspora visible on international stages and continued to find new ways to speak to audiences. His career shows both the force of that reach and the responsibility that comes with it."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-wyclef-jean-2026' AND slug='wyclef-jean-influence-haitienne-diaspora-fugees' AND locale='fr' AND status='published' AND demo=0 AND updated_at='2026-10-09T00:00:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-wyclef-jean-2026-pt-BR', 'article', id, updated_at, 'pt-BR', '{"title":"Wyclef Jean: a voz haitiana que levou a diáspora ao centro da música popular","subtitle":"Dos Fugees a projetos que misturam música e participação pública, sua trajetória mostra como um artista pode levar a identidade haitiana aos palcos mundiais e por que visibilidade também traz responsabilidade.","image_credit":"Collision Conf, foto de Stephen McCarthy / Sportsfile, Wikimedia Commons — CC BY 2.0. Foto sem alterações.","body":"Quando Wyclef Jean subiu para receber um Grammy com a bandeira haitiana sobre os ombros, ofereceu à diáspora uma imagem fácil de guardar: um artista criado nos Estados Unidos que não escondia de onde sua família veio. Esse gesto acompanha uma carreira construída com música e também com a capacidade de levar uma história haitiana a conversas muito mais amplas que o hip-hop. [Embaixada do Haiti nos Estados Unidos](https://www.haiti.org/dt_team/wyclef-jean/)\n\n## Da infância no Haiti aos Fugees\n\nNascido em Croix-des-Bouquets, perto de Porto Príncipe, Jean foi morar com os pais no Brooklyn aos nove anos. Mais tarde, a família se estabeleceu em Nova Jersey. No fim dos anos 1980, ele formou um grupo com Lauryn Hill e Pras Michel. Os Fugees alcançaram sucesso internacional com The Score, lançado em 1996. Segundo o perfil publicado pela Embaixada do Haiti, o álbum chegou ao primeiro lugar da Billboard e ganhou dois prêmios Grammy. [Embaixada do Haiti nos Estados Unidos](https://www.haiti.org/dt_team/wyclef-jean/)\n\nTrinta anos depois, o álbum continua reunindo públicos. Em agosto de 2026, Jean e Hill o apresentaram na íntegra durante o festival Diaspora Calling!, no Reino Unido, em comemoração ao aniversário do disco. O repertório e o retorno da dupla lembram que algumas obras não ficam apenas nas paradas: tornam-se referências compartilhadas por várias gerações. [Associated Press](https://ny1.com/nyc/all-boroughs/ap-top-news/2026/08/05/qa-ms-lauryn-hill-on-the-diaspora-calling-festival-in-the-uk-the-fugees-legacy-and-dangelo)\n\n## Uma influência que vai além das canções\n\nA fama musical de Jean também foi usada na vida pública. Em 2007, o presidente haitiano René Préval o nomeou embaixador itinerante, encarregado de promover a imagem do país no exterior. O cargo oficial reconhecia o alcance de seu nome, mas não o transformava em diplomata de carreira. [Reuters](https://www.reuters.com/article/lifestyle/rapper-wyclef-jean-to-be-haitis-roving-ambassador-idUSN03411270/)\n\nSua influência às vezes aparece em formatos inesperados. Em 2024, ele produziu “Paper Right”, uma faixa feita com a TIAA e vários artistas sobre poupança e transmissão de patrimônio. Na época, a Reuters informou que a música havia passado de 600 mil reproduções e gerado mais de US$ 100 mil em doações para a First Generation Investors, organização que ensina noções de investimento a estudantes do ensino médio de comunidades desfavorecidas. A abordagem é clara: levar um tema raramente associado à música para um formato que os jovens querem ouvir. [Reuters](https://www.reuters.com/business/finance/new-money-advice-wyclef-jean-just-dropped-its-rap-2024-02-26/)\n\n## Fama não substitui responsabilidade\n\nA história da Yéle Haiti lembra que o engajamento público precisa de uma gestão transparente. Depois do terremoto de 2010, a organização cofundada por Jean pediu doações para o Haiti. Mais tarde, suas finanças foram questionadas, e reportagens abordaram pagamentos contestados. Em 2011, a Reuters citou Jean reconhecendo que a organização havia cometido erros, mas negando ter usado dinheiro da Yéle para fins pessoais. A entidade encerrou as atividades em 2012, enquanto as perguntas sobre sua gestão continuavam. [Reuters](https://www.reuters.com/article/lifestyle/wyclef-jean-squandered-haitian-relief-funds-report-idUSTRE7AQ0T2/) · [TheGrio](https://thegrio.com/2012/10/15/wyclef-jeans-charity-yele-haiti-shuts-down-amid-financial-scandal/)\n\nEssa parte da trajetória não resume sua música, mas faz parte de sua história pública. Quando uma celebridade pede ao público que apoie uma causa, a boa intenção não basta: prestação de contas, resultados e respostas às críticas também fazem parte da confiança.\n\nWyclef Jean continua sendo uma figura de influência cultural haitiana porque tornou uma identidade e uma diáspora visíveis em palcos internacionais e seguiu buscando novas formas de conversar com o público. Sua trajetória mostra tanto a força desse alcance quanto a responsabilidade que o acompanha."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-wyclef-jean-2026' AND slug='wyclef-jean-influence-haitienne-diaspora-fugees' AND locale='fr' AND status='published' AND demo=0 AND updated_at='2026-10-09T00:00:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
INSERT INTO translations(id,target_type,target_id,version,locale,data,manual,created_at) SELECT 'geovyora-wyclef-jean-2026-es', 'article', id, updated_at, 'es', '{"title":"Wyclef Jean: la voz haitiana que llevó a la diáspora al centro de la música popular","subtitle":"De los Fugees a proyectos que combinan música y participación pública, su trayectoria muestra cómo un artista puede llevar la identidad haitiana a escenarios mundiales y por qué la visibilidad también exige responsabilidad.","image_credit":"Collision Conf, fotografía de Stephen McCarthy / Sportsfile, Wikimedia Commons — CC BY 2.0. Fotografía sin modificar.","body":"Cuando Wyclef Jean subió a recoger un Grammy con la bandera haitiana sobre los hombros, ofreció a la diáspora una imagen fácil de recordar: un artista formado en Estados Unidos que no ocultaba de dónde venía su familia. Ese gesto acompaña una carrera construida con música y también con la capacidad de llevar una historia haitiana a conversaciones mucho más amplias que el hip-hop. [Embajada de Haití en Estados Unidos](https://www.haiti.org/dt_team/wyclef-jean/)\n\n## De una infancia haitiana a los Fugees\n\nNacido en Croix-des-Bouquets, cerca de Puerto Príncipe, Jean se reunió con sus padres en Brooklyn a los nueve años. Más tarde, su familia se instaló en Nueva Jersey. A finales de los años ochenta formó un grupo con Lauryn Hill y Pras Michel. Los Fugees alcanzaron el éxito internacional con The Score, publicado en 1996. Según el perfil de la Embajada de Haití, el álbum llegó al primer puesto de la lista Billboard y ganó dos premios Grammy. [Embajada de Haití en Estados Unidos](https://www.haiti.org/dt_team/wyclef-jean/)\n\nTreinta años después, el álbum sigue reuniendo a públicos. En agosto de 2026, Jean y Hill lo interpretaron completo en el festival Diaspora Calling!, en el Reino Unido, para celebrar su aniversario. El repertorio y el regreso del dúo recuerdan que algunas obras no se quedan solo en las listas: se convierten en referencias compartidas por varias generaciones. [Associated Press](https://ny1.com/nyc/all-boroughs/ap-top-news/2026/08/05/qa-ms-lauryn-hill-on-the-diaspora-calling-festival-in-the-uk-the-fugees-legacy-and-dangelo)\n\n## Una influencia que va más allá de las canciones\n\nLa fama musical de Jean también se ha aprovechado en la vida pública. En 2007, el presidente haitiano René Préval lo nombró embajador itinerante para promover la imagen del país en el extranjero. El cargo oficial reconocía el alcance de su nombre, pero no lo convertía en diplomático de carrera. [Reuters](https://www.reuters.com/article/lifestyle/rapper-wyclef-jean-to-be-haitis-roving-ambassador-idUSN03411270/)\n\nSu influencia aparece a veces en formatos inesperados. En 2024 produjo “Paper Right”, una canción realizada con TIAA y varios artistas sobre el ahorro y la transmisión del patrimonio. Reuters informó entonces de que el tema había superado las 600.000 reproducciones y generado más de 100.000 dólares en donaciones para First Generation Investors, una organización que enseña nociones básicas de inversión a estudiantes de secundaria de comunidades desfavorecidas. El método es claro: presentar un tema poco asociado a la música en un formato que los jóvenes quieren escuchar. [Reuters](https://www.reuters.com/business/finance/new-money-advice-wyclef-jean-just-dropped-its-rap-2024-02-26/)\n\n## La fama no sustituye la responsabilidad\n\nLa historia de Yéle Haiti recuerda que la participación pública necesita una gestión clara. Tras el terremoto de 2010, la organización cofundada por Jean pidió donaciones para Haití. Más tarde surgieron preguntas sobre sus finanzas y reportajes sobre pagos cuestionados. En 2011, Reuters citó a Jean reconociendo que la organización había cometido errores, aunque negó haber usado dinero de Yéle para fines personales. La entidad cerró en 2012, mientras continuaban las preguntas sobre su gestión. [Reuters](https://www.reuters.com/article/lifestyle/wyclef-jean-squandered-haitian-relief-funds-report-idUSTRE7AQ0T2/) · [TheGrio](https://thegrio.com/2012/10/15/wyclef-jeans-charity-yele-haiti-shuts-down-amid-financial-scandal/)\n\nEsta parte de su trayectoria no resume su música, pero pertenece a su historia pública. Cuando una celebridad invita al público a apoyar una causa, la buena intención no basta: las cuentas, los resultados y las respuestas a las críticas también forman parte de la confianza.\n\nWyclef Jean sigue siendo una figura influyente de la cultura haitiana porque hizo visible una identidad y una diáspora en escenarios internacionales, y continuó buscando nuevas formas de hablar con el público. Su trayectoria muestra tanto la fuerza de ese alcance como la responsabilidad que conlleva."}', 1, '2026-10-12T00:00:00+00:00' FROM articles WHERE id='geovyora-wyclef-jean-2026' AND slug='wyclef-jean-influence-haitienne-diaspora-fugees' AND locale='fr' AND status='published' AND demo=0 AND updated_at='2026-10-09T00:00:00+00:00' ON CONFLICT(target_type,target_id,version,locale) DO UPDATE SET data=excluded.data,manual=1;
